/* MIT. Skill information uses the same prerequisites as learning, in both directions. */
#ifndef MYRO_SKILL_INFO55_H
#define MYRO_SKILL_INFO55_H
static unsigned skill_info_requires55(const Combat*g,unsigned skill,unsigned requirement){unsigned found=0,rank=0;if(g->jobId>=J60_NINJA){for(unsigned i=0;i<sizeof(expandedPrereqs60)/sizeof(*expandedPrereqs60);i++){const uint16_t*p=expandedPrereqs60[i];if((p[0]==g->jobId||p[0]==J60_TAEKWON&&(g->jobId==J60_STAR_GLADIATOR||g->jobId==J60_SOUL_LINKER))&&p[1]==skill){found=1;if(p[2]==requirement)rank=p[3];}}if(found)return rank;}if(g->jobId==J52_SUPER_NOVICE){for(unsigned i=0;i<sizeof(superNeeds53)/sizeof(*superNeeds53);i++){const uint16_t*p=superNeeds53[i];if(p[0]==skill){found=1;if(p[1]==requirement)rank=p[2];}}if(found)return rank;}
 for(unsigned i=0;i<sizeof(transPrereqs52)/sizeof(*transPrereqs52);i++){const uint16_t*p=transPrereqs52[i];if(p[0]==g->jobId&&p[1]==skill){found=1;if(p[2]==requirement)rank=p[3];}}if(found)return rank;
 for(unsigned i=0;i<sizeof(classPrereqs48)/sizeof(*classPrereqs48);i++){const uint16_t*p=classPrereqs48[i];if(p[0]==job_parent52(g->jobId)&&p[1]==skill){found=1;if(p[2]==requirement)rank=p[3];}}if(found)return rank;
 int k=skill_rank_index(skill);if(k>=0&&learnNeeds[k]==requirement)return learnNeedsRank[k];if(skill==48&&job_parent52(g->jobId)!=17){if(requirement==22)return 7;if(requirement==23)return 5;}if(skill==31&&requirement==36)return 1;return 0;
}
static void skill_info_append55(char*out,size_t bytes,size_t*used,const char*format,...){if(*used>=bytes)return;va_list args;va_start(args,format);int n=vsnprintf(out+*used,bytes-*used,format,args);va_end(args);if(n<0)return;if((size_t)n>=bytes-*used)*used=bytes-1;else*used+=(size_t)n;}
static int skill_info_build55(const Combat*g,unsigned id,char*out,size_t bytes){if(!out||!bytes||id>=SKILL_COUNT)return 0;size_t used=0;out[0]=0;int k=skill_rank_index(id);unsigned learned=k>=0?g->ranks[k]:skill_rank(g,id),maximum=k>=0?learnMax[k]:learned;skill_info_append55(out,bytes,&used,"%s\n%s%s | Learned %u/%u\n\n%s\n\n",skillDefs[id].name,skill_passive(id)?"Passive":"Active",skill_quest(id)?" | Quest skill":"",learned,maximum,skillDefs[id].help);
 if(!skill_passive(id))skill_info_append55(out,bytes,&used,"Selected rank: %u | SP: %d\n",skill_rank(g,id)>0?skill_rank(g,id):1,skill_cost(g,id));
 const ExpandedRequirement60*cost=expanded_requirement60(id);if(cost&&!skill_passive(id)){unsigned r=skill_rank(g,id);if(r<1)r=1;if(r>10)r=10;r--;if(cost->zeny[r])skill_info_append55(out,bytes,&used,"Zeny: %u\n",cost->zeny[r]);if(cost->coins[r])skill_info_append55(out,bytes,&used,"Coins: %u\n",cost->coins[r]);if(cost->ammoCount[r])skill_info_append55(out,bytes,&used,"Ammunition: %u (X in Items selects ammo)\n",cost->ammoCount[r]);for(unsigned i=0;i<cost->count;i++){int item=inventory_catalog52(cost->items[i].source);if(item>=0)skill_info_append55(out,bytes,&used,"%s: %u\n",itemDefs[item].name,cost->items[i].amount[r]);}if(cost->state==1)skill_info_append55(out,bytes,&used,"Requires Hiding.\n");if(cost->weapons){static const char*names[]={"Unarmed","Dagger","1H Sword","2H Sword","1H Spear","2H Spear","1H Axe","2H Axe","Mace","Rod","Bow","Book","2H Rod","Knuckle","Instrument","Whip","Katar","Revolver","Rifle","Gatling","Shotgun","Grenade Launcher","Huuma Shuriken"};skill_info_append55(out,bytes,&used,"Weapon:");for(unsigned i=0;i<23;i++)if(cost->weapons&(1u<<i))skill_info_append55(out,bytes,&used," %s;",names[i]);skill_info_append55(out,bytes,&used,"\n");}}
 skill_info_append55(out,bytes,&used,"\nRequires:\n");unsigned requirements=0;for(unsigned other=1;other<SKILL_COUNT;other++){unsigned rank=skill_info_requires55(g,id,other);if(rank){requirements++;int index=skill_rank_index(other);unsigned have=index>=0?g->ranks[index]:skill_rank(g,other);skill_info_append55(out,bytes,&used,"%s %u (learned %u)\n",skillDefs[other].name,rank,have);}}if(!requirements)skill_info_append55(out,bytes,&used,skill_quest(id)?"Taught by its quest.\n":"No prerequisite skill.\n");
 skill_info_append55(out,bytes,&used,"\nLeads into:\n");unsigned leads=0;for(unsigned n=0;n<class_count(g);n++){unsigned next=class_skill(g,(int)n),rank=skill_info_requires55(g,next,id);if(rank){leads++;skill_info_append55(out,bytes,&used,"%s (requires this at %u)\n",skillDefs[next].name,rank);}}if(!leads)skill_info_append55(out,bytes,&used,"No direct follow-on skill in this class tree.\n");return 1;
}
#endif
